#!/usr/bin/env python3
# AI DISCLAIMER: All of the text in this file was generated by AI.
"""G019D: score .8's disk commits on a stock base (HDD VM, arms B, C, F; stage 1 no cap, stage 2 MEM_MAX=1536M)
against the predictions H6-H11 written before the runs (README.md).

Reads the stage dir's results.txt (RESULT, WINDOW, CACHEDROP lines, labels g019d-s<stage>-r<n>-<arm>) and log.txt (BIN_B/C/F),
and counts ERROR-level lines in each run dir's monerod.log (run dirs matched by the label at the end of their name).
The heavy part is windows k=2..7, as in the .8 release test: its rate is 6,000 blocks over the sum of those windows' seconds, its reads the
mean of their read_kB_per_block.
Ratios are of medians (2 runs an arm: their mean); "no overlap" when the two arms' ranges are disjoint.
usage: python3 scripts/score.py data/stage data/runs"""
import os, re, statistics, sys

TOP_HASH = "5a956cc4b1d19d21423fa11292a1c5f2496111e1a7d39562f4d2287284036361"
HEAVY = range(2, 8)
STAGES = {"1": "none", "2": "1536M"}
SHA = {"B": "9cbc14e01d662007", "C": "c42bb0716561ccd0", "F": "682824085782f6ce"}


def num(v):
    try:
        return float(v)
    except (TypeError, ValueError):
        return None


def fields(line):
    return dict(m.groups() for m in re.finditer(r"(\S+?)=(\S*)", line))


stage_dir, run_root = sys.argv[1], sys.argv[2]
runs, problems = {}, []
for line in open(os.path.join(stage_dir, "results.txt")):
    kind = line.split(" ", 2)[1] if line.count(" ") >= 2 else ""
    f = fields(line)
    m = re.match(r"g019d-s([12])-r(\d)-([BCF])$", f.get("label", ""))
    if not m:
        continue
    r = runs.setdefault(f["label"], {"stage": m.group(1), "n": int(m.group(2)), "arm": m.group(3), "win": {}})
    if kind == "RESULT":
        r["f"] = f
    elif kind == "WINDOW":
        r["win"][int(f["k"])] = (num(f.get("secs")), num(f.get("read_kB_per_block")))
    elif kind == "CACHEDROP":
        r["cd"] = f

for lab, r in runs.items():
    d = [x for x in os.listdir(run_root) if x.endswith("-" + lab)]
    if len(d) != 1:
        problems.append("%s: %d run dirs" % (lab, len(d)))
        r["err"] = None
        continue
    log = open(os.path.join(run_root, d[0], "monerod.log"), errors="replace").read()
    r["err"] = sum(1 for l in log.splitlines() if len(l.split("\t")) > 2 and l.split("\t")[2].strip() == "ERROR")  # the level field
    r["cdlog"] = log.count("LMDB page cache drop: on")
    w = r["win"]
    if all(k in w and w[k][0] and w[k][1] is not None for k in HEAVY):
        r["rate"] = 1000 * len(HEAVY) / sum(w[k][0] for k in HEAVY)
        r["kb"] = statistics.mean(w[k][1] for k in HEAVY)
    else:
        r["rate"] = r["kb"] = None
        problems.append("%s: heavy windows missing" % lab)

binl = open(os.path.join(stage_dir, "log.txt")).read()
for a, s in SHA.items():
    if not re.search(r"^BIN_%s \S+ \(%s\)" % (a, s), binl, re.M):
        problems.append("log.txt: BIN_%s is not sha16 %s" % (a, s))

g = lambda r, k: num(r["f"].get(k))
print("%-14s %-7s %4s %9s %9s %8s %9s %9s %8s %8s %6s %5s %5s %4s" % (
    "run", "outcome", "arm", "heavy_b/s", "heavy_kB", "launch_s", "cpu_s", "rssanon", "cg_anon", "refault", "oomk", "cdrop", "ERROR", "hash"))
for lab in sorted(runs, key=lambda l: (runs[l]["stage"], runs[l]["n"])):
    r = runs[lab]; f = r["f"]
    print("%-14s %-7s %4s %9.3f %9.1f %8.1f %9.1f %9s %8s %8s %6s %5s %5s %4s" % (
        lab[6:], f.get("outcome"), r["arm"], r["rate"], r["kb"], g(r, "launch_to_top_s"), g(r, "cpu_s"), f.get("rss_anon_max_MB"),
        f.get("cg_anon_max_MB"), f.get("cg_refault_file"), f.get("cg_oom_kill"), r["cdlog"], r["err"],
        "ok" if f.get("hash_at_3113400") == TOP_HASH else "BAD"))


def arm(st, a, fn):
    return [fn(r) for r in runs.values() if r["stage"] == st and r["arm"] == a]


def ratio(st, a, b, fn, label):
    x, y = arm(st, a, fn), arm(st, b, fn)
    q = statistics.median(x) / statistics.median(y)
    dis = max(x) < min(y) or max(y) < min(x)
    print("  stage %s %s %s/%s %.3f (%s %s against %s %s; %s)" % (st, label, a, b, q, a, "-".join("%.4g" % v for v in sorted(x)),
          b, "-".join("%.4g" % v for v in sorted(y)), "no overlap" if dis else "overlap"))
    return q, dis


rate = lambda r: r["rate"]
kb = lambda r: r["kb"]
ltop = lambda r: g(r, "launch_to_top_s")
cpu = lambda r: g(r, "cpu_s")
res = {}
for st in "12":
    print("stage %s (%s)" % (st, STAGES[st]))
    for a in "BCF":
        print("  arm %s: heavy b/s %s; heavy kB/block %s; launch_to_top_s %s; cpu_s %s; rss_anon_max_MB %s" % (
            a, arm(st, a, rate), [round(v, 1) for v in arm(st, a, kb)], arm(st, a, ltop), arm(st, a, cpu),
            arm(st, a, lambda r: g(r, "rss_anon_max_MB"))))
    for a, b in (("C", "B"), ("F", "B"), ("F", "C")):
        res[(st, a, b)] = ratio(st, a, b, rate, "heavy rate")
        ratio(st, a, b, ltop, "launch_to_top_s (time)")
        ratio(st, a, b, cpu, "cpu_s")

v = {}
def say(h, ok, text):
    v[h] = ok
    print("%s %s: %s" % (h, "met" if ok else "NOT met", text))

for p in problems:
    print("PROBLEM " + p)
allr = list(runs.values())
say("H6", len(allr) == 12 and not problems
    and all(r["f"].get("outcome") == "ok" and r["f"].get("hash_at_3113400") == TOP_HASH and r["err"] == 0 for r in allr)
    and all((r["cdlog"] == 1 and r["cd"].get("on") == "1") if r["arm"] in "CF" else (r["cdlog"] == 0 and r["cd"].get("lines") == "0") for r in allr)
    and all(r["f"].get("cg_oom_kill") in ("0", "na") for r in allr),
    "12 runs, all ok with the hash at 3,113,400 and 0 ERROR lines; the cache-drop line once in each C and F run, never in B; no OOM kill")
cb, fb = res[("1", "C", "B")][0], res[("1", "F", "B")][0]
say("H7", 0.94 <= cb <= 1.02 and 0.94 <= fb <= 1.02, "no cap: C/B %.3f, F/B %.3f (band 0.94-1.02)" % (cb, fb))
q = res[("2", "F", "B")][0]
say("H8", 2.0 <= q <= 3.5, "1536M: F/B %.3f (band 2.0-3.5)" % q)
cb, fc = res[("2", "C", "B")][0], res[("2", "F", "C")][0]
say("H9", 1.4 <= cb <= 3.2 and 1.0 <= fc <= 1.9, "1536M: C/B %.3f (band 1.4-3.2), F/C %.3f (band 1.0-1.9)" % (cb, fc))
bk, fk = arm("2", "B", kb), arm("2", "F", kb)
say("H10", min(bk) >= 100 and max(fk) <= 40, "1536M heavy reads kB/block: B %s (at least 100), F %s (at most 40)" % (
    [round(x, 1) for x in bk], [round(x, 1) for x in fk]))
br = [g(r, "rss_anon_max_MB") for r in allr if r["arm"] == "B"]
say("H11", max(br) <= 700, "B's peak RssAnon %s MB (at most 700 in every run)" % br)
